// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    VaultAdapter c;

    function setUp() public {
        c = new VaultAdapter();
    }

    function _run(address _vault, address _asset) internal {
        vm.assume(_vault != address(0));
        bool firstReverted;
        try c.rate(_vault, _asset) returns (uint256 r1) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool secondReverted;
        uint256 latest;
        try c.rate(_vault, _asset) returns (uint256 r2) {
            secondReverted = false;
            latest = r2;
        } catch {
            secondReverted = true;
            latest = 0;
        }
        assertTrue(!(secondReverted) ? latest >= 0 : true);
    }

    function testFuzz_run(address _vault, address _asset) public {
        vm.assume(_vault.code.length == 0 && uint160(_vault) > 0xffff && _vault != address(this) && _vault != address(c) && _vault != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _vault != 0x000000000000000000636F6e736F6c652e6c6f67 && _vault != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _vault != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(_asset.code.length == 0 && uint160(_asset) > 0xffff && _asset != address(this) && _asset != address(c) && _asset != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _asset != 0x000000000000000000636F6e736F6c652e6c6f67 && _asset != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _asset != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_vault, _asset);
    }

    receive() external payable {}
}
